import numpy as np
from collections import Counter
def solve(inp):
    H,W=len(inp),len(inp[0]); inp=np.array(inp)
    bg=Counter(inp.flatten().tolist()).most_common(1)[0][0]
    # object = largest connected component (8-conn) of non-bg cells
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); comp.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=a+dr,b+dc
                            if 0<=rr<H and 0<=cc<W and inp[rr][cc]!=bg and (rr,cc) not in seen:
                                st.append((rr,cc))
                comps.append(comp)
    comps.sort(key=len,reverse=True)
    obj=comps[0]
    cnt={}
    for r,c in obj: cnt[inp[r][c]]=cnt.get(inp[r][c],0)+1
    seed_col=cnt  # the color inside object
    out=inp.copy()
    def norm_comp(cells):
        rs=[a for a,b in cells]; cs=[b for a,b in cells]
        r0,c0=min(rs),min(cs)
        return sorted([(a-r0,b-c0) for a,b in cells])
    pat=norm_comp(obj)
    # stamp: for each non-bg isolated-ish cell whose color==seed_col and not in object
    for r in range(H):
        for c in range(W):
            v=inp[r][c]
            if v==bg or v not in set(cnt.values()) or (r,c) in set(map(tuple,obj)) or v!=list(cnt.keys())[0]:
                pass
    # find seed color: colors inside object, excluding bg; assume unique non-bg color(s)
    seed_cols={v for r,c in obj for v in [inp[r][c]]}-{bg}
    seed_col=list(seed_cols)[0]
    for r in range(H):
        for c in range(W):
            if inp[r][c]==seed_col and (r,c) not in set(map(tuple,obj)):
                # find stamp offset: seed corresponds to which pattern cell? demo: pattern[1][0]=3
                tr,tc=None,None
                for p_cell in pat:
                    pv,pr,pc=p_cell[0],p_cell[1],p_cell[2]
                    if pv==seed_col: tr,tc=pr,pc
                if tr is not None:
                    r0,c0=r-tr,c-tc
                    for pr,pc,pv in pat:
                        rr,cc=r0+pr,c0+pc
                        if 0<=rr<H and 0<=cc<W and inp[rr][cc]==bg:
                            out[rr][cc]=pv
    # L-tail for other isolated markers (colors != seed_col, not bg, not part of object)
    for r in range(H):
        for c in range(W):
            v=inp[r][c]
            if v not in (bg,) and (r,c) not in set(map(tuple,obj)) and v!=seed_col:
                for dr,dc in ((-1,0),(-2,-1)):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<H and 0<=cc<W and inp[rr][cc]==bg:
                        out[rr][cc]=6
    return out.tolist()
