def fibrule(a,b):
    # guess: out[i][j] = in[p(i)][q(j)] with p,q mod h,w
    H,W=len(b),len(b[0]); h,w=len(a),len(a[0])
    sols=[]
    for pi in range(h):
        for qj in range(w):
            ok=all(b[i][j]==a[pi%h][qj%w] for i in range(H) for j in range(W))
            if ok: sols.append((pi,qj))
    return sols

