def f2(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    def dist(r,c,target): return abs(r-target[0])+abs(c-target[1])
    # iterate: mark each 9 as value of closest non-noise,non-bg neighbor
    noise=9
    changed=True
    while changed:
        changed=False
        for r in range(H):
            for c in range(W):
                v=g[r][c]
                if v!=noise and v!=bg: continue
                # nearest non-noise, non-bg cell
                best=None
                for dr in range(-H,H+1):
                    for dc in range(-W,W+1):
                        nr,nc=r+dr,c+dc
                        if not(0<=nr<H and 0<=nc<W): continue
                        nv=g[nr][nc]
                        if nv==noise or nv==bg: continue
                        d=abs(dr)+abs(dc)
                        if best is None or d<best[0]: best=(d,nv)
                if best:
                    out[r][c]=best[1]; changed=True
    return out
