import itertools
from collections import Counter as C2
def regions(cells):
    # simple flood fill over grid positions
    pts=set(cells)
    comps=[]
    seen=set()
    for p in cells:
        if p in seen: continue
        stack=[p]; comp=[]
        while stack:
            c=stack.pop(); seen.add(c)
            comp.append(c); 
            for dq in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(c[0]+dq[0],c[1]+dq[1])
                if q in pts and q not in seen: stack.append(q)
        comps.append(sorted(comp))
    return comps
