W=len(ti[0]); H=len(ti)
def f(g):
    g=[r[:] for r in g]; bg=max(sum(r) for r in [] ) or None
    import collections
    cnt=collections.Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    out=[[bg]*len(g[0]) for _ in range(len(g))]
    for i,r in enumerate(g):
        for j,x in enumerate(r):
            if x!=bg:
                out[i][j]=x; out[i][W-1-j]=x
    return out
o=f(ti)
